import { useTooltip } from './TooltipContext';
import styles from './Tooltip.module.css'; // Create a CSS module for styling

const Tooltip = ({ id, children, content }) => {
  const { openTooltipId, closeTooltip } = useTooltip();
  const [isVisible, setIsVisible] = useState(false);

  useEffect(() => {
    if (openTooltipId === id) {
      setIsVisible(true);
    } else {
      setIsVisible(false);
    }
  }, [openTooltipId, id]);

  useEffect(() => {
    return () => {
      closeTooltip(); // Close the tooltip when it unmounts
    };
  }, [closeTooltip]);

  return (
    <>
      {isVisible && (
        <div className={styles.tooltip}>
          {content}
        </div>
      )}
    </>
  );
};

export default Tooltip;
