        choices.add(choice);
        choiceToNodeMap.put(choice.getChoiceNumber(), choice.getNextNodeId());
    }

    public Integer getNextNodeId(int choiceNumber) {
        return choiceToNodeMap.get(choiceNumber);
    }
}

